const upsertPending = `-- name: UpsertPending :one
INSERT INTO content_pending (entity_type, entity_id, document, updated_by)
VALUES ($1, $2, $3, $4)
ON CONFLICT (entity_type, entity_id) DO UPDATE SET document = EXCLUDED.document, updated_by = EXCLUDED.updated_by, updated_at = now()
RETURNING updated_at
`

type UpsertPendingParams struct {
	EntityType string
	EntityID   uuid.UUID
	Document   []byte
	UpdatedBy  uuid.UUID
}

func (q *Queries) UpsertPending(ctx context.Context, arg UpsertPendingParams) (time.Time, error) {
	row := q.db.QueryRow(ctx, upsertPending,
		arg.EntityType,
		arg.EntityID,
		arg.Document,
		arg.UpdatedBy,
	)
	var updated_at time.Time
	err := row.Scan(&updated_at)
	return updated_at, err
}
